WITH valid AS (SELECT id, country, city, rating, CONCAT(city, ' ', supplier_name) AS city_supplier_name, REPLACE(supplier_name, ' ', '') AS supplier_name_slug, COALESCE(city, 'DIRECT') AS city_filled FROM suppliers WHERE city IS NOT NULL) SELECT *, NTILE(3) OVER (PARTITION BY country, city ORDER BY rating, id) AS rating_bucket, ROW_NUMBER() OVER (PARTITION BY country ORDER BY rating, id) AS row_seq, ROUND(rating / SUM(rating) OVER (PARTITION BY country), 4) AS rating_share, AVG(rating) OVER (ORDER BY rating, id ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS rating_avg_6_prior FROM valid WHERE country = 'DE';
